/// Local Data Storage ID of the shared catalogs. The PDK scopes it to this
/// policy binding.
const CATALOG_STORAGE_ID: &str = "catalogs";

/// Remembered `(event, catalog)` pairs of the per-worker `warn` rate limiter.
const WARN_LIMITER_CAPACITY: usize = 1024;

/// One policy binding, as seen by one worker.
struct Policy {
    config: Config,
    caller_attributes: Option<Script>,
    catalog_partition: Option<Script>,
    /// `apiInstanceKey` of the catalog key.
    api_instance: String,
    /// `configFingerprint` of the catalog key.
    fingerprint: String,
    /// Worker-local catalog copies over the shared store.
    catalogs: RefCell<Catalogs<LocalStore>>,
    limiter: RefCell<WarnLimiter>,
    clock: Clock,
}

/// What the logs need to know about the request being handled.
struct RequestInfo {
    request_id: Option<String>,
    client_id: Option<String>,
    /// The client accepts only `text/event-stream` (so a refusal is framed as SSE).
    sse_only: bool,
}

/// A `tools/list` request, carried from the request to the response phase.
struct ListRequest {
    info: RequestInfo,
    pending: Pending,
}

/// What the request phase hands to the response phase: only a `tools/list`
/// request needs its response handled.
type Carried = Option<ListRequest>;

impl RequestInfo {
    fn context<'a>(&'a self, policy: &'a Policy, caller: Option<&'a Caller>) -> Context<'a> {
        Context {
            api_instance: &policy.api_instance,
            request_id: self.request_id.as_deref(),
            client_id: self.client_id.as_deref(),
            caller_attributes: caller.map(|caller| &caller.attributes),
        }
    }
}

/// Request headers by lowercase name. Repeated headers are joined with `,`
/// so that a second value cannot hide behind the first.
struct Headers(BTreeMap<String, String>);

impl Headers {
    fn new(list: Vec<(String, String)>) -> Headers {
        let mut map: BTreeMap<String, String> = BTreeMap::new();
        for (name, value) in list {
            map.entry(name.to_ascii_lowercase())
                .and_modify(|joined| {
                    joined.push(',');
                    joined.push_str(&value);
                })
                .or_insert(value);
        }
        Headers(map)
    }

    fn get(&self, name: &str) -> Option<&str> {
        self.0.get(name).map(String::as_str)
    }
}

impl Policy {
    fn now_ms(&self) -> u64 {
        self.clock
            .now()
            .duration_since(UNIX_EPOCH)
            .map(|elapsed| u64::try_from(elapsed.as_millis()).unwrap_or(u64::MAX))
            .unwrap_or(0)
    }

    /// Logs one event, subject to `logging.*` and the `warn` rate limit.
    fn log(&self, event: &Event<'_>, context: &Context<'_>, catalog: Option<&str>) {
        let now = self.now_ms();
        let prepared = {
            let mut limiter = self.limiter.borrow_mut();
            guard_log::prepare(
                event,
                context,
                &self.config.logging,
                &mut limiter,
                catalog,
                now,
            )
        };
        match prepared {
            Some((LogLevel::Debug, line)) => logger::debug!("{}", line),
            Some((LogLevel::Info, line)) => logger::info!("{}", line),
            Some((LogLevel::Warn, line)) => logger::warn!("{}", line),
            None => {}
        }
    }

    /// The caller and its level. An unset expression or one
    /// that fails to evaluate gives no attributes, so only `defaultLevel`.
    fn caller(
        &self,
        handler: &dyn HeadersHandler,
        stream: &StreamProperties,
        auth: Option<&AuthenticationData>,
        info: &RequestInfo,
    ) -> Caller {
        let value = self.caller_attributes.as_ref().and_then(|script| {
            let value = evaluate(script, handler, stream, auth);
            if value.is_none() {
                self.log(
                    &Event::CallerAttributesUnavailable,
                    &info.context(self, None),
                    None,
                );
            }
            value
        });
        let json = value.as_ref().map(to_json);
        let attributes = decide::normalize_attributes(
            json.as_ref(),
            self.config.caller_attribute_separator.as_deref(),
        );
        Caller::new(&self.config, attributes)
    }

    /// The catalog key for this request.
    fn catalog_key(
        &self,
        handler: &dyn HeadersHandler,
        stream: &StreamProperties,
        auth: Option<&AuthenticationData>,
    ) -> Result<String, PartitionUnavailable> {
        let value = self
            .catalog_partition
            .as_ref()
            .and_then(|script| evaluate(script, handler, stream, auth));
        let partition =
            catalog::partition_key(&self.config, value.as_ref().and_then(ScriptValue::as_str))?;
        Ok(catalog::catalog_key(
            &self.api_instance,
            &self.fingerprint,
            &partition,
        ))
    }

    /// A request the guard cannot safely interpret. In audit mode it
    /// is forwarded and logged as `would_deny` instead.
    fn reject(&self, err: ProtocolError, info: &RequestInfo) -> Flow<Carried> {
        self.log(
            &Event::protocol(&self.config, &err),
            &info.context(self, None),
            None,
        );
        match decide::action_for(&self.config, true) {
            Action::Refuse => {
                Flow::Break(into_response(response::protocol_error(&err, info.sse_only)))
            }
            Action::Forward | Action::ForwardWouldDeny => Flow::Continue(None),
        }
    }

    /// Decides every request element of a body that contains `tools/call`
    /// and refuses the whole body if any element is refused.
    fn decide(
        &self,
        batch: bool,
        requests: &[RequestElement],
        caller: &Caller,
        key: Result<String, PartitionUnavailable>,
        info: &RequestInfo,
    ) -> Flow<Carried> {
        let now = self.now_ms();
        let decisions = {
            let mut catalogs = self.catalogs.borrow_mut();
            let max_age_seconds = catalogs.settings().max_age_seconds;
            let catalog = key.as_ref().ok().map(|key| catalogs.read(key));
            decide::decide_requests(requests, &self.config, caller, |name| match catalog {
                None => Lookup::PartitionUnavailable,
                Some(catalog) => Lookup::Catalog(CatalogView {
                    pin: catalog.pin(name),
                    stale: catalog.is_stale(now, max_age_seconds),
                }),
            })
        };

        let context = info.context(self, Some(caller));
        let catalog = key.as_deref().ok();
        if key.is_err() {
            self.log(&Event::PartitionUnavailable, &context, None);
        }
        for (element, (id, decision)) in requests.iter().zip(&decisions) {
            match (decision, &element.call) {
                (ElementDecision::Call(CallDecision::Deny(refusal)), _) => {
                    self.log(&Event::refusal(&self.config, refusal), &context, catalog);
                }
                (
                    ElementDecision::Call(CallDecision::Allow { class, .. }),
                    CallCheck::Call { name },
                ) => {
                    let event = Event::CallAllowed {
                        tool: name,
                        class: *class,
                        caller_level: caller.level,
                    };
                    self.log(&event, &context, catalog);
                }
                (ElementDecision::InvalidParams(detail), _) => {
                    let err = ProtocolError::InvalidParams {
                        id: id.clone(),
                        detail: *detail,
                    };
                    self.log(&Event::protocol(&self.config, &err), &context, catalog);
                }
                _ => {}
            }
        }

        let refused = decisions.iter().any(|(_, decision)| decision.is_refused());
        match decide::action_for(&self.config, refused) {
            Action::Refuse => Flow::Break(into_response(self.refusal_reply(
                batch,
                &decisions,
                info.sse_only,
            ))),
            Action::Forward | Action::ForwardWouldDeny => Flow::Continue(None),
        }
    }

    /// Runs one list-processing step with this worker's catalogs; its events
    /// are logged with the request's context.
    fn with_list<R>(
        &self,
        request: &ListRequest,
        step: impl FnOnce(&Pending, &mut Env<'_, LocalStore>) -> R,
    ) -> R {
        let context = request.info.context(self, Some(&request.pending.caller));
        let mut log = |event: &Event<'_>, catalog: Option<&str>| self.log(event, &context, catalog);
        let mut catalogs = self.catalogs.borrow_mut();
        let mut env = Env {
            config: &self.config,
            catalogs: &mut catalogs,
            now_ms: self.now_ms(),
            log: &mut log,
        };
        step(&request.pending, &mut env)
    }

    fn refusal_reply(
        &self,
        batch: bool,
        decisions: &[(Id, ElementDecision)],
        sse_only: bool,
    ) -> Reply {
        if batch {
            return response::batch_refusal(decisions, &self.config, sse_only);
        }
        match decisions.first() {
            Some((id, ElementDecision::Call(CallDecision::Deny(refusal)))) => {
                response::policy_refusal(refusal, id, &self.config, sse_only)
            }
            // A single message is either one refused call or not refused at
            // all; anything else is an internal error and still fails closed.
            other => response::protocol_error(
                &ProtocolError::Internal {
                    id: other.map(|(id, _)| id.clone()),
                },
                sse_only,
            ),
        }
    }
}

/// Evaluates a DataWeave property with the bindings its schema declares
/// (`attributes` and `authentication`). `None` on any evaluation error.
fn evaluate(
    script: &Script,
    handler: &dyn HeadersHandler,
    stream: &StreamProperties,
    auth: Option<&AuthenticationData>,
) -> Option<ScriptValue> {
    let mut evaluator = script.evaluator();
    evaluator.bind_attributes(&HandlerAttributesBinding::new(handler, stream));
    if let Some(auth) = auth {
        evaluator.bind_authentication(auth);
    }
    evaluator.eval().ok()
}

/// Only strings and arrays can carry caller attributes; anything
/// else becomes `null`, which `normalize_attributes` treats as no attributes.
fn to_json(value: &ScriptValue) -> serde_json::Value {
    match value {
        ScriptValue::String(s) => serde_json::Value::String(s.clone()),
        ScriptValue::Array(items) => serde_json::Value::Array(items.iter().map(to_json).collect()),
        _ => serde_json::Value::Null,
    }
}

fn into_response(reply: Reply) -> Response {
    let headers: Vec<(String, String)> = reply
        .headers
        .into_iter()
        .map(|(name, value)| (name.to_owned(), value))
        .collect();
    Response::new(u32::from(reply.status))
        .with_headers(headers)
        .with_body(reply.body)
}

/// Test hook for a manual check: a real Wasm trap, not a policy error, so
/// the test observes the gateway's Wasm failure mode.
#[cfg(feature = "test-trap")]
fn test_trap(headers: &Headers) {
    if headers.get("x-guard-test-trap").is_some() {
        #[cfg(target_arch = "wasm32")]
        core::arch::wasm32::unreachable();
        #[cfg(not(target_arch = "wasm32"))]
        std::process::abort();
    }
}

#[cfg(not(feature = "test-trap"))]
fn test_trap(_headers: &Headers) {}

async fn request_filter(
    state: RequestState,
    stream: StreamProperties,
    authentication: Authentication,
    policy: &Policy,
) -> Flow<Carried> {
    let state = state.into_headers_state().await;
    let headers = Headers::new(state.handler().headers());
    test_trap(&headers);
    let auth = authentication.authentication();
    let info = RequestInfo {
        request_id: headers.get("x-request-id").map(str::to_owned),
        client_id: auth.as_ref().and_then(|auth| auth.client_id.clone()),
        sse_only: response::wants_sse_only(headers.get("accept")),
    };

    // Method rules.
    match envelope::gate_request(&state.method(), |name| headers.get(name)) {
        Gate::PassThrough => return Flow::Continue(None),
        Gate::Refuse(refusal) => return policy.reject(refusal.into(), &info),
        Gate::Inspect => {}
    }

    // Stop iteration: nothing reaches the upstream until this filter
    // returns.
    let state = state.into_headers_body_state().await;
    let handler = state.handler();
    let body = handler.body();
    if let Err(refusal) =
        envelope::check_body_size(body.len(), policy.config.limits.max_request_body_bytes)
    {
        return policy.reject(refusal.into(), &info);
    }
    let limits = EnvelopeLimits {
        max_batch_size: policy.config.limits.max_batch_size,
        max_tool_name_bytes: policy.config.limits.max_tool_name_bytes,
    };
    let routing =
        match envelope::inspect_request(&body, headers.get("mcp-protocol-version"), limits) {
            Ok(routing) => routing,
            Err(err) => return policy.reject(err.into(), &info),
        };

    match routing {
        Routing::PassThrough => Flow::Continue(None),
        Routing::ExpectList(ids) => {
            // The response must arrive uncompressed to be inspected.
            handler.set_header("accept-encoding", "identity");
            let handler: &dyn HeadersHandler = handler;
            let caller = policy.caller(handler, &stream, auth.as_ref(), &info);
            let key = policy.catalog_key(handler, &stream, auth.as_ref());
            let pending = Pending { ids, caller, key };
            Flow::Continue(Some(ListRequest { info, pending }))
        }
        Routing::Decide { batch, requests } => {
            let handler: &dyn HeadersHandler = handler;
            let caller = policy.caller(handler, &stream, auth.as_ref(), &info);
            let key = policy.catalog_key(handler, &stream, auth.as_ref());
            policy.decide(batch, &requests, &caller, key, &info)
        }
    }
}

/// Marks the catalog stale when it is dropped while armed: the gateway ended
/// a list response (body over its buffer limit, upstream reset, timeout)
/// after its headers were accepted for inspection but before its body was
/// complete, so the list was never inspected.
struct Unfinished<'a> {
    policy: &'a Policy,
    request: &'a ListRequest,
    armed: bool,
}

impl Unfinished<'_> {
    /// The whole body arrived: nothing to mark.
    fn finished(mut self) {
        self.armed = false;
    }
}

impl Drop for Unfinished<'_> {
    fn drop(&mut self) {
        if self.armed {
            self.policy.with_list(self.request, list::on_incomplete);
        }
    }
}

/// `tools/list` responses. The headers are checked first, so a
/// response that cannot be filtered is never buffered.
async fn response_filter(state: ResponseState, data: RequestData<Carried>, policy: &Policy) {
    let RequestData::Continue(Some(request)) = data else {
        return;
    };
    let state = state.into_headers_state().await;
    let status = u16::try_from(state.status_code()).unwrap_or(0);
    let headers = Headers::new(state.handler().headers());
    let mode = policy.with_list(&request, |pending, env| {
        list::on_headers(
            status,
            headers.get("content-encoding"),
            headers.get("content-type"),
            pending,
            env,
        )
    });
    let Some(mode) = mode else {
        return;
    };

    // Stop iteration: the client receives nothing until this filter returns.
    // If the gateway ends the response before the whole body arrives, this
    // future is dropped while it waits, and the guard marks the catalog stale.
    let unfinished = Unfinished {
        policy,
        request: &request,
        armed: true,
    };
    let state = state.into_headers_body_state().await;
    unfinished.finished();
    let handler = state.handler();
    let body = handler.body();
    let new_body = match policy.with_list(&request, |pending, env| {
        list::on_body(mode, &body, pending, env)
    }) {
        Outcome::Forward => return,
        Outcome::ForwardNoStore => {
            for (name, value) in &list::HeaderChanges::no_store().set {
                handler.set_header(name, value);
            }
            return;
        }
        Outcome::Rewrite(new_body) => new_body.into_bytes(),
    };
    // The guard must change this list. If the gateway refuses the new body
    // (it is over the gateway's buffer limit), the client gets an error
    // instead of a list that should have been filtered.
    let written = if handler.set_body(&new_body).is_ok() {
        new_body
    } else {
        let errors = policy.with_list(&request, |pending, env| {
            list::on_rewrite_refused(mode, &body, pending, env)
        });
        if handler.set_body(&errors).is_err() {
            policy.with_list(&request, list::on_rewrite_failed);
            return;
        }
        errors
    };
    // The PDK does not adjust Content-Length after `set_body`.
    let changes = list::header_changes(written.len(), headers.get("content-length").is_some());
    for name in changes.remove {
        handler.remove_header(name);
    }
    for (name, value) in &changes.set {
        handler.set_header(name, value);
    }
}

/// Describes a serde error without echoing any configuration value.
fn describe(err: &serde_json::Error) -> String {
    format!(
        "{:?} error at line {}, column {}",
        err.classify(),
        err.line(),
        err.column()
    )
}

#[entrypoint]
async fn configure(
    launcher: Launcher,
    Configuration(bytes): Configuration,
    metadata: Metadata,
    storage: DataStorageBuilder,
    clock: Clock,
) -> Result<()> {
    // An error here makes the gateway answer every request with 503: the
    // policy fails closed on an invalid configuration.
    let config = Config::from_json(&bytes).map_err(|err| anyhow!("{err}"))?;
    let schema: SchemaConfig = serde_json::from_slice(&bytes).map_err(|err| {
        anyhow!(
            "invalid mcp-tool-annotation-guard configuration: {}",
            describe(&err)
        )
    })?;

    let api_instance = metadata
        .api_metadata
        .id
        .clone()
        .filter(|id| !id.is_empty())
        .unwrap_or_else(|| metadata.policy_metadata.filter_name.clone());

    // Nothing is evicted: an index per API instance and configuration admits
    // at most `limits.maxCatalogs` catalogs. Catalogs of an earlier
    // configuration are removed first.
    let fingerprint = catalog::classification_fingerprint(&config.classification);
    let store = LocalStore::new(storage.local(CATALOG_STORAGE_ID));
    catalog::remove_other_configurations(&store, &api_instance, &fingerprint);
    let catalogs = Catalogs::new(
        store,
        CatalogSettings::from_config(&config),
        catalog::index_key(&api_instance, &fingerprint),
    );

    let policy = Policy {
        fingerprint,
        catalogs: RefCell::new(catalogs),
        limiter: RefCell::new(WarnLimiter::new(WARN_LIMITER_CAPACITY)),
        caller_attributes: schema.caller_attributes,
        catalog_partition: schema.catalog_partition,
        api_instance,
        config,
        clock,
    };
    let startup = Context {
        api_instance: &policy.api_instance,
        ..Context::default()
    };
    policy.log(
        &Event::LimitsConfigured(&policy.config.limits),
        &startup,
        None,
    );

    let filter = on_request(
        |state: RequestState, stream: StreamProperties, authentication: Authentication| {
            request_filter(state, stream, authentication, &policy)
        },
    )
    .on_response(|state: ResponseState, data: RequestData<Carried>| {
        response_filter(state, data, &policy)
    });
    launcher.launch(filter).await?;
    Ok(())
}

